const ideas=JSON.parse(document.querySelector('#content').textContent);
const discussion=JSON.parse(document.querySelector('#discussion').textContent);
const feedback=JSON.parse(document.querySelector('#feedback').textContent);
const assets=JSON.parse(document.querySelector('#assets').textContent);
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cues=[['1M02','Arrival','01:31'],['1M18','Calling Harry','04:02'],['1M34','Confrontation','07:55'],['1M23','Ik Weet Je Te Vinden','01:36'],['1M06','6 Maanden Eerder','00:29'],['1M40','Gun Point','00:32'],['1M41','Escape','02:37'],['1M17',"Lucy’s Escape",'00:27'],['1M10','Er Tussen Uit / Fontane','03:37'],['1M24','Ray Sees Lucy','01:41'],['1M21','Poisoning Ray','01:18'],['1M15','Ray Wakes Up','02:49'],['1M38','Love Theme','04:30'],['1M09A','Party’s Death','02:21'],['1M09B','De Kleine Meid','00:32'],['1M01','Shanghai','01:15'],['1M27','Party’s Painting','02:15'],['1M22','Oog Om Oog','01:01'],['1M20','Aymen Sees Ray','01:30'],['1M26','Iron Wire','02:53'],['1M11','Dood En Begraven','00:54'],['1M43','Finale','02:32'],['1M16','Life Insurance','01:45'],['1M28','Harry’s Plan','01:43'],['1M07','No Benzine','00:30'],['1M05','Church','00:59']];
let active=null,variant='A',film=false,toastTimer;
const variants={},decisions={},implementationChoices={};
try{const saved=JSON.parse(localStorage.getItem('mandocues-implementatie-v1')||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))Object.assign(implementationChoices,saved);}catch{}
try{Object.assign(decisions,JSON.parse(localStorage.getItem('mandocues-suggesties-v2')||'{}'));}catch{}
function draft(){return {id:'draft',text:'',at:null,originalAt:null,clockAt:null,measure:'',measureScope:'bar',page:null,source:null};}
function metadataNote(t,id){return id==='draft'?t?.draft:t?.notes.find(n=>n.id===id);}
function newTake(c,n,rolling=false,kind='take'){return {id:`c${c}-${kind==='overdub'?'od':'t'}${n}`,kind,cue:c,num:n,label:'',rolling,started:null,duration:n===1?64:91,cursor:n===1?31:42,base:rolling?42:0,rating:n===1?4:3,best:n===1,notes:[],draft:draft()};}
function fresh(id){
 const ts=cues.map((c,j)=>j===0?[newTake(j,1),newTake(j,2,id==='notities')]:j===1?[newTake(j,1)]:[]);
 if(id==='cue-take'){
  ts[0].push(newTake(0,3));ts[1].push(newTake(1,2));
  ts[0].forEach((t,i)=>Object.assign(t,{rating:[4,3,5][i],best:i===2,collapsed:true}));
  ts[1].forEach((t,i)=>Object.assign(t,{rating:[4,2][i],best:i===0,collapsed:true}));
 }
 ts[0][0].notes=[{id:'seed-1',text:'Nice entrance; keep this.',at:31,measure:18,page:1,source:'example-v1'}];
 ts[0][1].notes=[{id:'seed-2',text:'Cello a little calmer in bar 18.',at:38,measure:18,page:1,source:'example-v1'}];
 // Populated examples let the reviewer try cue/take changes immediately.
 if(id==='partituur'){
  ts[1].push(newTake(1,2));ts[2].push(newTake(2,1),newTake(2,2));
  for(const j of [1,2])for(const t of ts[j])t.notes=[{id:`example-${j}-${t.num}`,text:t.num===1?'Keep the phrasing at the opening.':'Try a softer entrance.',at:24,measure:1,page:1,source:productionScoreDoc(cues[j][0]).id,instruments:[...scoreInstrumentIds]}];
 }
 for(const t of ts.flat())for(const n of t.notes){n.clockAt=Date.now()-(6-t.num)*60000;n.createdAt=n.clockAt;}
 if(id==='partituur')for(const t of ts[0])t.scoreSelections={[assets.production.id]:(t.num===1?[1,2,3,4,7,8,9]:[5,6]).flatMap(m=>scoreInstrumentIds.map(i=>scoreCellKey(m,i)))};
 if(id==='partituur')for(const t of ts[0])for(const n of t.notes){n.source=assets.production.id;n.instruments=t.num===2?['vc']:[...scoreInstrumentIds];syncSavedScorePage(n);}
 return {cue:0,minRating:0,open:new Set([0]),cueFold:new Set(),takes:ts,selected:ts[0].at(-1).id,cueNotes:cues.map((_,j)=>j===0?[{id:'cue-seed-'+j,text:'Watch the transition into bar 18.'}]:[]),cueDrafts:cues.map(()=>''),page:1,measure:null,zoom:1,doc:id==='partituur'?productionScoreDoc():{id:'example-v1',name:'Demo score',url:null,pages:2},noteSerial:2,...(id==='planning'?{booked:180,elapsed:42,remaining:140}:{})};
}
const states=Object.fromEntries(ideas.map(i=>[i.id,fresh(i.id)]));
function state(){return states[active.id];}
function allTakes(s){return s.takes.flat();}
function takeById(s,id){return allTakes(s).find(t=>t.id===id);}
function running(s){return allTakes(s).find(t=>t.rolling);}
function position(t){return t.rolling?t.base+(t.started?Math.floor((Date.now()-t.started)/1000):0):t.cursor;}
function formatLocalClock(ms,seconds=true){return new Date(ms).toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',...(seconds?{second:'2-digit'}:{}),hour12:true});}
function parseLocalClock(value){
 const match=value.trim().match(/^(\d{1,2}):([0-5]\d)(?::([0-5]\d))?\s*(AM|PM)?$/i);if(!match)return null;
 let hours=+match[1];const period=match[4]?.toUpperCase();if(period){if(hours<1||hours>12)return null;hours=hours%12+(period==='PM'?12:0);}else if(hours>23)return null;
 return {hours,minutes:+match[2],seconds:+(match[3]||0)};
}
function formatWallClock(){return formatLocalClock(Date.now());}
function time(n){n=Math.max(0,Math.floor(n||0));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2700);}
function promptBody(i,v){return `Gewenst gedrag:\n${i.requirement}\n\n${Object.keys(i.variants).length>1?'Variant '+v:'Uitwerking'}:\n${i.variants[v]}\n\nControle:\n${i.accept}${i.inspection?'\n\nContext uit het bestaande scherm:\n'+i.inspection:''}${i.context?'\n\nErvaring uit Floris’ andere project:\n'+i.context:''}`;}
function promptFor(i,v){return `Vrijblijvende suggestie van ${i.origin||'Floris'}: ${i.short}${Object.keys(i.variants).length>1?', variant '+v:''}. Pas dit toe op mijn bestaande app. Mijn code, ontwerpkeuzes en oordeel blijven leidend. Bekijk eerst wat er al bestaat; behoud de bestaande visuele stijl en werk met bestaande componenten, state en opslag. Het prototype toont voorbeelddata, geen voorgeschreven architectuur. Alle tekst in de daadwerkelijke GUI moet Engels zijn, inclusief knoppen, labels, hints, tooltips, toegankelijkheidslabels en meldingen. Gebruik bijvoorbeeld Best, Add, Edit, Delete, Bar en Book p. Vragen, uitleg en voorstellen voor de collega mogen Nederlands blijven. Vertaal geen oorspronkelijke cue-/projectnamen of zelf ingevoerde notities.\n\n${promptBody(i,v)}\n\nMaak een kleine samenhangende wijziging, controleer de bestaande flows en vat kort samen wat veranderd is. Implementeer alleen dit voorstel. Neem andere suggesties alleen mee waar het hierboven expliciet nodig is voor de getoonde flow.`;}
function implementationChoice(key,i){const saved=implementationChoices[key];return {on:saved?.on===true,variant:i?(i.variants[saved?.variant]?saved.variant:(i.variants[variants[i.id]]?variants[i.id]:'A')):null};}
function smallSuggestions(){return discussion.filter(d=>d.small).sort((a,b)=>a.order-b.order);}
function openQuestions(){return discussion.filter(d=>!d.small);}
function selectableNotes(){return discussion.filter(d=>!d.questionOnly);}
function selectedImplementations(){return [...[...smallSuggestions(),...openQuestions()].filter(d=>!d.questionOnly).filter(d=>implementationChoice('note:'+d.id).on).map(d=>({d})),...ideas.filter(i=>implementationChoice('idea:'+i.id,i).on).map(i=>({i,v:implementationChoice('idea:'+i.id,i).variant}))];}
function combinedPrompt(){const selected=selectedImplementations();if(!selected.length)return '';return `Geselecteerde suggesties voor mijn bestaande MandoCues-app. Ik heb onderstaande onderdelen gekozen; implementeer alleen deze selectie. Mijn code, ontwerpkeuzes en oordeel blijven leidend. Bekijk eerst wat al bestaat en behoud de bestaande stijl, componenten, state en opslag. De prototypes tonen voorbeelddata. Alle tekst in de daadwerkelijke GUI moet Engels zijn, inclusief knoppen, labels, hints, tooltips, toegankelijkheidslabels en meldingen. Gebruik bijvoorbeeld Best, Add, Edit, Delete, Bar en Book p. Vragen, uitleg en voorstellen voor de collega mogen Nederlands blijven. Vertaal geen oorspronkelijke cue-/projectnamen of zelf ingevoerde notities.\n\nStem de gekozen onderdelen op elkaar af. Gedeelde eisen worden één keer geïmplementeerd met dezelfde data en bediening. Onderdelen die expliciet nodig zijn binnen een gekozen suggestie horen daarbij; voeg geen andere suggesties of alternatieve varianten toe. Voorbeeldkoppelingen zijn geen bewijs van echte recorder-, film- of partituurherkenning.\n\n`+selected.map(({i,v,d},n)=>i?`## ${n+1}. ${i.short}${Object.keys(i.variants).length>1?' — '+i[v.toLowerCase()]:''}\n\n${promptBody(i,v)}`:`## ${n+1}. ${d.title}\n\n${d.text}`).join('\n\n---\n\n')+'\n\nVoer de geselecteerde aanpassingen samenhangend uit, controleer de bestaande flows en de controles hierboven. Geef kort aan wat je hebt aangepast, getest en wat nog een echte bronkoppeling vereist.';}
function implementationNoteRow(d){const key='note:'+d.id,c=implementationChoice(key);return `<div class="implementation-row"><label class="implementation-check"><input type="checkbox" data-implementation-choice="${key}" ${c.on?'checked':''}><span><b>${esc(d.title)}</b><small>${esc(d.label)}</small></span></label></div>`;}
function implementationIdeaRow(i){const key='idea:'+i.id,c=implementationChoice(key,i);return `<div class="implementation-row"><label class="implementation-check"><input type="checkbox" data-implementation-choice="${key}" ${c.on?'checked':''}><span><b>Prototype ${i.number} · ${esc(i.short)}</b><small>${esc(i.question)}</small></span></label>${Object.keys(i.variants).length>1?`<label class="implementation-variant">Variant<select data-implementation-variant="${key}" aria-label="Variant voor ${esc(i.short)}" ${c.on?'':'disabled'}>${Object.keys(i.variants).map(v=>`<option value="${v}" ${c.variant===v?'selected':''}>${esc(i[v.toLowerCase()])}</option>`).join('')}</select></label>`:`<span class="implementation-single">${esc(i.a)}</span>`}</div>`;}
function implementationBuilder(){return `<section class="implementation-builder" id="voor-claude" aria-labelledby="implementation-title"><div class="section-line"><span>Jouw keuze voor Claude</span></div><h2 id="implementation-title">Wat wil je overnemen?</h2><p class="implementation-intro">Vink de kleine aanpassingen en grotere voorstellen aan die je wilt gebruiken. Kies bij een prototype eventueel een variant. De bestaande teksten worden samengevoegd tot één prompt.</p><div class="implementation-options"><div class="implementation-small-label">Kleine aanpassingen</div>${smallSuggestions().map(implementationNoteRow).join('')}<div class="implementation-small-label">Grotere voorstellen · de prototypes</div>${ideas.map(implementationIdeaRow).join('')}${openQuestions().some(d=>!d.questionOnly)?`<div class="implementation-small-label">Mogelijke uitbreiding</div>${openQuestions().filter(d=>!d.questionOnly).map(implementationNoteRow).join('')}`:''}</div><div class="implementation-actions"><span id="implementation-count" role="status">${selectedImplementations().length} gekozen</span><button class="copy-button" data-action="copy-bundle" ${selectedImplementations().length?'':'disabled'}>Kopieer selectie voor Claude</button><button class="text-button" data-action="download-bundle" ${selectedImplementations().length?'':'disabled'}>Download als document ↓</button></div><details class="implementation-preview"><summary>Bekijk samengestelde prompt</summary><pre class="bundle-preview" tabindex="0">${esc(combinedPrompt()||'Vink eerst één of meer suggesties aan.')}</pre></details><p class="implementation-footnote">Je keuze wordt waar mogelijk in deze browser bewaard. ‘Interessant’ of een demo bekijken vinkt niets automatisch aan.</p></section>`;}
function updateImplementationChoice(el){const key=el.dataset.implementationChoice||el.dataset.implementationVariant;if(!key)return false;const i=ideas.find(i=>'idea:'+i.id===key);if(!i&&!discussion.some(d=>'note:'+d.id===key))return true;const value=implementationChoice(key,i);if(el.dataset.implementationChoice)value.on=el.checked;else if(i?.variants[el.value])value.variant=el.value;implementationChoices[key]=value;try{localStorage.setItem('mandocues-implementatie-v1',JSON.stringify(implementationChoices));}catch{}const select=el.closest('.implementation-row')?.querySelector('select');if(select)select.disabled=!value.on;const count=selectedImplementations().length;$('#implementation-count').textContent=count+' gekozen';document.querySelectorAll('[data-action="copy-bundle"],[data-action="download-bundle"]').forEach(b=>b.disabled=!count);$('.bundle-preview').textContent=combinedPrompt()||'Vink eerst één of meer suggesties aan.';return true;}
function handover(){return `# Prototypes van Floris\n\nEen paar kleine suggesties voor je opnameprogramma. Open index.html, probeer een voorbeeld en kies eventueel A of B. Bevalt iets? De knop ‘Kopieer prompt’ geeft je de volledige opdracht voor je eigen Claude. Neem alleen mee wat jij handig vindt. Jouw programma en ontwerpkeuzes gaan voor.\n\nFilmmodus verbergt de uitleg voor een schermopname; Escape toont die weer. Alle voorbeelden werken lokaal. Er wordt geen audio opgenomen. Notities en zelfgekozen PDF’s blijven in deze geopende demo en verdwijnen bij herladen; er wordt niets geüpload.\n\n`+smallSuggestionsMarkdown()+openQuestionsMarkdown()+String.fromCharCode(10,10)+'## De prototypes'+String.fromCharCode(10,10)+ideas.map(i=>`## ${i.number} — ${i.short}\n\nDe vraag: ${i.question}\n\n${i.group==='aanvullend'?'Aanvullend voorstel.':'De kleine aanpassingen uit het overzicht zijn in dit voorbeeld alvast meegenomen.'}${i.extra?' '+i.extra:''}\n\n${i.why}\n\n${i.tradeoff}\n\n${i.comment?i.comment+'\n\n':''}Probeer: ${i.try}\n\n${decisions[i.id]?'Mijn indruk: '+decisions[i.id]+'\n\n':''}${Object.keys(i.variants).map(v=>`### ${i[v.toLowerCase()]}\n\n${promptFor(i,v)}\n`).join('\n')}`).join('\n---\n\n');}
function saveFile(name,text,type='text/markdown;charset=utf-8'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function art(n){if(n===0)return `<div class="mini-window"><div class="mini-line"><b>⌄ &nbsp; 1M02</b><span>Arrival</span><span>3 takes</span></div><div class="mini-take">↳ Take 1 <small>★★★★☆</small></div><div class="mini-take">↳ Take 2 <small>★★★☆☆</small></div><div class="mini-take">↳ Take 3 <small>★★★★★</small></div></div>`;if(n===1)return `<div class="mini-window"><div class="mini-toolbar"><b>1M02 · Take 2</b><span>00:42</span><i>■ Stop</i></div><div class="mini-line"><b>↳ Take 2</b><span>Notes</span></div><div class="mini-note">00:38 · Cello iets rustiger.</div><div class="mini-line">1M18 <span>Calling Harry</span></div></div>`;if(n===2)return `<div class="mini-window"><div class="mini-line"><b>1M02 → Take 2</b><span>2 notities</span></div><div class="mini-note"><b>00:38 · maat 18</b><br>Cello iets rustiger.</div><div class="mini-note">Typ je opmerking… <span style="float:right">Enter ↵</span></div></div>`;return `<div class="mini-window mini-score"><div class="tiny-score"><img src="${assets.production.pageImages[1]}" alt=""></div><div class="mini-note">Take 2 · 00:38 · <b>maat 18 ↗</b></div></div>`;}
function smallSuggestionsMarkdown(){const nl=String.fromCharCode(10);return nl+nl+'## Kleine aanpassingen'+nl+nl+smallSuggestions().map(d=>'- '+d.bullet+(d.origin?' ('+d.origin+')':'')).join(nl);}
function openQuestionsMarkdown(){const nl=String.fromCharCode(10);return openQuestions().length?nl+nl+'## Vragen'+nl+nl+openQuestions().map(d=>'- '+d.title+(d.text?' '+d.text:'')).join(nl)+nl:'';}
function discussionMarkdown(){return smallSuggestionsMarkdown()+openQuestionsMarkdown();}
function smallSuggestionItems(items){return items.map(d=>`<li id="${d.id}">${esc(d.bullet)}${d.origin?` <small class="source-tag">${esc(d.origin)}</small>`:''}</li>`).join('');}
function smallSuggestionsSection(){const base=smallSuggestions().filter(d=>d.group!=='aanvullend'),extra=smallSuggestions().filter(d=>d.group==='aanvullend');return `<section class="small-suggestions" id="vragen" aria-labelledby="small-suggestions-title"><div class="section-line"><span>Eerst een paar kleine aanpassingen</span></div><h2 id="small-suggestions-title">Is dit niet handiger?</h2><ul class="small-suggestions-list">${smallSuggestionItems(base)}</ul>${extra.length?`<details class="extra-small-additions"><summary>Meer kleine voorstellen · ${extra.length} kleine voorstellen</summary><ul>${smallSuggestionItems(extra)}</ul></details>`:''}</section>`;}
function prototypeCard(i){const n=ideas.indexOf(i);return `<a class="suggestion-card" href="#${i.id}"><div class="card-art art-${n+1}" aria-hidden="true">${n<4?art(n):extraArt(i.id)}</div><div class="card-body"><div class="card-kicker"><span class="num">${i.number}</span><span>${i.tag}</span></div><h2>${esc(i.question)}</h2><p>${esc(i.preview)}</p><div class="card-footer"><span>${decisions[i.id]?esc(decisions[i.id]):'Bekijk & probeer'}</span><span aria-hidden="true">↗</span></div></div></a>`;}
function discussionSection(){const questions=openQuestions();return questions.length?`<section class="open-questions" aria-labelledby="open-questions-title"><h2 id="open-questions-title">Vragen</h2><ul>${questions.map(d=>`<li>${esc(d.title)}${d.text?' '+esc(d.text):''}${d.link?` <a href="#${d.link}">${esc(d.linkText)}</a>`:''}</li>`).join('')}</ul></section>`:'';}
function home(){active=null;film=false;document.body.classList.remove('film');document.title='Prototypes van Floris';$('#app').innerHTML=`<main class="home"><div class="home-intro"><div><div class="eyebrow">MandoCues · een paar ideeën</div><h1>Prototypes<br><em>van Floris.</em></h1></div><div class="intro-copy"><p>Eerst kleine suggesties en een paar vragen. Daaronder kun je de prototypes proberen.</p><small>Een paar ideeën van mij, geen voorstel om je hele workflow om te gooien. Neem alleen mee wat jij handig vindt.</small></div></div>${smallSuggestionsSection()}${discussionSection()}${extraPurpose()}<section class="prototype-collection" aria-labelledby="prototype-collection-title"><div class="section-line"><span>De grotere vragen</span><span>${String(ideas.length).padStart(2,'0')} prototypes · bekijken & proberen</span></div><h2 id="prototype-collection-title">Hoe zou dat kunnen werken?</h2><p class="prototype-collection-intro">Hier zijn een paar prototypes waarin de kleine voorstellen alvast zijn meegenomen. Elk voorbeeld onderzoekt één grotere vraag; bij sommige kun je A en B vergelijken.</p><div class="cards">${ideas.filter(i=>i.group!=='aanvullend').map(prototypeCard).join('')}</div><div class="section-line new-questions-line"><span>Andere vragen</span></div><div class="cards">${ideas.filter(i=>i.group==='aanvullend').map(prototypeCard).join('')}</div></section>${implementationBuilder()}<footer class="home-foot"><div><strong>Even laten zien hoe het werkt</strong>Gebruik Filmmodus om een voorbeeld op je scherm op te nemen. Escape brengt de uitleg terug.</div><div><strong>Jouw programma, jouw keuzes</strong>Elk idee is vrijblijvend. Kies onderaan wat je wilt overnemen en kopieer één prompt voor je Claude.<br><button class="text-button" data-action="export-feedback">Alle notes van Floris ↓</button></div></footer></main>`;}
function openIdea(id){const i=ideas.find(i=>i.id===id);if(!i){home();return;}active=i;variant=i.variants[variants[id]]?variants[id]:'A';document.title=`${i.short} — Prototypes van Floris`;$('#app').innerHTML=`<div class="workspace"><aside class="side-nav"><a href="#" class="back-link">← Alle suggesties</a><div class="eyebrow">Prototypes van Floris</div>${ideas.map(j=>`<a class="nav-item ${id===j.id?'active':''}" href="#${j.id}" ${id===j.id?'aria-current="page"':''}><span>${j.number}</span>${j.short}</a>`).join('')}<a class="nav-item discussion-nav" href="#vragen">Kleine aanpassingen</a><a class="nav-item" href="#extra-input">Aanvullende input</a><a class="nav-item" href="#voor-claude">Kies voor Claude →</a><div class="side-note">Even proberen.<br>Overnemen als het past.<br><br>Voorbeelddata.<br>Geen echte audio-opname.</div></aside><main class="work-main"><div class="work-heading"><div><div class="eyebrow">Prototype ${i.number} · ${i.tag}</div><h1>${esc(i.question)}</h1><p>${esc(i.preview)}</p><small class="prototype-context">${i.group==='aanvullend'?'Aanvullend voorstel.':'De <a href="#vragen">kleine aanpassingen uit het overzicht</a> zijn hier alvast meegenomen.'}${i.extra?` <span class="extra-addition">${esc(i.extra)}</span>`:''}</small></div><div class="heading-actions"><button class="copy-button top-copy" data-action="copy">Kopieer prompt${Object.keys(i.variants).length>1?' '+variant:''}</button><button class="film-button" data-action="film">${film?'↙ Terug naar uitleg':'⛶ Filmmodus'}</button></div></div><div class="lab-toolbar"><div class="variant-group" role="group" aria-label="Prototypevariant">${Object.keys(i.variants).length>1?Object.keys(i.variants).map(v=>`<button data-variant="${v}" aria-pressed="${variant===v}">${i[v.toLowerCase()]}</button>`).join(''):`<span class="single-variant">${i.a}</span>`}</div><div class="lab-actions"><button data-action="reset">↺ Reset demo</button></div></div><div class="browser-frame"><div class="frame-bar"><span class="frame-dots" aria-hidden="true"><i></i><i></i><i></i></span><span class="frame-caption">MandoCues / ${id==='partituur'?'Comp tool':'Recording'} · interactive demo</span></div><div class="demo" id="demo" lang="en"></div></div>${id==='bediening'?controlReview():''}<div class="try-bar"><b>Probeer</b><span>${i.try}</span></div><div class="explanation concise"><section><h2>Is dit niet handiger?</h2><p>${i.why}</p><p>${i.tradeoff}</p>${i.comment?`<p class="prototype-comment">${esc(i.comment)}</p>`:''}</section><section><div class="prompt-card"><div class="prompt-head"><h2>Wil je dit overnemen?</h2><button class="copy-button" data-action="copy">Kopieer prompt${Object.keys(i.variants).length>1?' '+variant:''}</button></div><p>Plak deze ene prompt in je eigen Claude. Hij bevat ook de context die nodig is. Jouw code en keuzes gaan voor.</p><details><summary>Lees de prompt</summary><pre class="prompt-text" tabindex="0">${esc(promptFor(i,variant))}</pre></details></div><div class="decision"><span>Mijn indruk:</span>${['Interessant','Nog twijfelen','Overslaan'].map(d=>`<button data-decision="${d}" aria-pressed="${decisions[id]===d}">${d}</button>`).join('')}</div></section></div></main></div>`;renderDemo();}
function demoTop(sub=''){return `<div class="demo-top"><div class="demo-title"><span style="color:#9c92ff">◉</span> Recording<small>After Party · String quartet · 20 October</small></div><div class="demo-view-actions"><span class="demo-pill">${sub||'Demo'}</span>${active?.id!=='partituur'?`<button type="button" data-action="toggle-main-score" data-score-toggle aria-expanded="${!!state().showMainScore}" aria-controls="main-score-pane">Score</button>`:''}</div></div>`;}
function cueAltKeys(s,cue){return s.takes?s.takes[cue].filter(t=>t.alt).map(t=>t.id):Object.keys(s.alts).filter(key=>s.alts[key]&&Number(key.split('-')[0])===cue).sort((a,b)=>Number(a.split('-')[1])-Number(b.split('-')[1]));}
function altLabel(s,cue,key){return 'Alt';}
function altCount(s,cue){const count=cueAltKeys(s,cue).length;return ' · Alts: '+count;}
function cueHeader(s,c,j,len,open,details,toggleAttr='open-cue'){return `<div class="cue-header"><button class="cue-fold-button" data-${toggleAttr}="${j}" aria-expanded="${open}" aria-controls="${details}" aria-label="${open?'Collapse':'Expand'} takes for ${c[0]}"><span class="chevron">${open?'⌄':'›'}</span></button><button class="cue-select-button" data-select-cue="${j}" ${s.cue===j?'aria-current="true"':''} aria-label="Choose cue ${c[0]} ${esc(c[1])}"><span class="cue-id">${c[0]}</span><span class="cue-name">${c[1]}</span>${sourceCueFacts(c,j)}<span class="cue-count">${entryCountText(s,j,len)}${altCount(s,j)}${s.cue===j?' · active':''}</span></button></div>`;}
function hierarchy(){const s=state();return recordingScreen(s,`<div class="review-filter"><label>Show takes <select data-rating-filter>${[[0,'All ratings'],[3,'3–5 stars'],[4,'4–5 stars'],[5,'Only 5 stars']].map(([n,label])=>`<option value="${n}" ${s.minRating===n?'selected':''}>${label}</option>`).join('')}</select></label></div>`+groupedList(s,{mode:'all',filter:s.minRating}), 'Cue → takes');}
function recordButton(s){if(s.unified&&s.sessionPausedAt)return '<button class="record" data-action="record">▶ Resume session <kbd>⌘ Enter</kbd></button>';if(s.unified&&!s.sessionStarted)return '<button class="record" data-action="record">▶ Start session <kbd>⌘ Enter</kbd></button>';const t=running(s);return `<button class="record ${t?'stop':''}" data-action="record">${t?'■ Stop '+(t.kind==='overdub'?'overdub':'take')+' <kbd>⌘ Enter</kbd>':'● Record '+cues[s.cue][0]+' · Take '+nextEntryNumber(s,s.cue,'take')+' <kbd>⌘ Enter</kbd>'}</button>`;}
function transport(s){const live=running(s),t=live||takeById(s,s.selected),c=cues[s.cue];return `<div class="transport ${live?'is-recording':'is-idle'}"><div class="identity"><span class="cue-id">${c[0]}</span><small>${esc(c[1])} · ${t?entryLabel(t):'No take yet'}</small><span class="rec-status ${live?'rolling':'standby'}">${live?'● RECORDING':'NOT RECORDING'}</span></div>${s.unified?`<div class="transport-clocks"><label>Time <b data-wall-clock>${formatWallClock()}</b></label>${proposalSchedule()}</div>`:''}<label class="transport-take-time">Take time <span class="timer" ${live?`data-live="${live.id}"`:''}>${time(live?position(live):t?.duration||0)}</span></label>${recordButton(s)}</div>`;}

function starRating(value,key,label,scope='take'){return `<div class="star-rating" role="group" aria-label="Rating ${esc(label)}">${[1,2,3,4,5].map(n=>`<button type="button" data-stars="${n}" data-rating-key="${key}" data-rating-scope="${scope}" aria-label="${n} ${n===1?'star':'stars'} for ${esc(label)}" aria-pressed="${value===n}"><span aria-hidden="true">${n<=value?'★':'☆'}</span></button>`).join('')}</div>`;}
// Demonstration anchors only: these do not analyse a PDF or listen to a performance.
function syncMeasureInputs(s,t){document.querySelectorAll(`[data-measure-input="${t.id}"]`).forEach(el=>{if(document.activeElement!==el)el.value=t.draft.measure;});}
function startNotes(s){const t=running(s)||s.takes[s.cue].at(-1);return `<section class="start-notes" aria-label="Notes beside the recording controls">${t?`<div class="start-notes-heading"><b>Notes for ${entryLabel(t)}</b>${starRating(t.rating,t.id,cues[t.cue][0]+' '+entryLabel(t))}</div>${composer(s,t,false,'top')}<div class="notes-scroll-heading">All notes for this take</div><div class="start-recent">${noteList(s,t,false,'top')}</div>`:'<h4>Notes</h4><p class="notes-empty">Start a take to write take notes. Cue notes are already available.</p>'}</section>`;}
function mainPanel(s,side=false){const t=running(s),c=cues[s.cue];return `<section class="main-panel ${side?'main-panel-side':''}" id="main-panel" aria-label="Recording controls">${side?'<div class="region-label fixed-region">Fixed controls</div>':''}<div class="main-recording"><div class="rec-status ${t?'rolling':'standby'}">${t?'● RECORDING · '+entryLabel(t).toUpperCase():'● STAND BY'}</div><div class="main-cue"><b>${c[0]}</b><strong>${c[1]}</strong></div><div class="main-metadata"><span>${c[2]} music</span><span>Medium</span><span>Planned ${time(cuePlannedMinutes(s.cue)*60)}</span></div><div class="main-buttons"><div class="take-control-group"><small>Take</small>${recordButton(s)}${!t?`<button class="overdub-button" data-action="record-overdub">Overdub ${nextEntryNumber(s,s.cue,'overdub')}</button>`:''}</div><div class="cue-control-group"><small>Cue</small><button data-action="prev-cue" ${t?'disabled':''}>← Previous</button><button data-action="next-cue" ${t?'disabled':''}>Next →</button></div></div><div class="main-take-time">Take time <b ${t?`data-live="${t.id}"`:''}>${time(t?position(t):0)}</b></div>${side?'':startNotes(s)}</div><div class="session-metrics"><div class="session-scope">Session</div><label>TIME <strong data-wall-clock>${formatWallClock()}</strong></label><div class="metric-grid"><label>SESSION ELAPSED <b>${active.id==='planning'?time(s.elapsed*60):'14:42'}</b></label><label>REMAINING <b>${active.id==='planning'?time(s.remaining*60):'5:45:18'}</b></label><label>PLANNED END <b>${active.id==='planning'?planningClock(600+s.booked):'00:59'}</b></label><label>PROJECTED END <b>${active.id==='planning'?planningClock(600+s.elapsed+s.remaining):'00:59'}</b></label></div>${active.id==='planning'?planningStatus(s)+planningInputs(s):'<div class="schedule-badge">On schedule<small>Demo schedule · 2 cues completed</small></div>'}${side?'':cueGeneral(s,s.cue,'top')}</div></section>`;}
function mainScorePane(s){
 const a=scoreAsset(productionScoreDoc(cues[s.cue][0]).id);
 return `<aside class="main-score-pane" id="main-score-pane" aria-label="Score for the current cue"><header><div><b>Score · ${cues[s.cue][0]}</b><small>${esc(cues[s.cue][1])} · bars ${a.measureRange.join('–')}</small></div><button type="button" data-action="toggle-main-score" aria-label="Hide score">×</button></header><div class="main-score-pages" data-score-cue="${s.cue}" tabindex="0" aria-label="Score pages for ${cues[s.cue][0]}">${a.bookPages.map((bookPage,index)=>`<figure><img src="${a===assets.production?assets.production.pageImages[index]:assets.production.bookImages[bookPage]}" width="1200" height="1698" alt="Score ${cues[s.cue][0]}, book page ${bookPage}"><figcaption>Book p. ${bookPage}</figcaption></figure>`).join('')}</div></aside>`;
}
function mountMainScore(s){
 if(!s.showMainScore||active.id==='partituur')return;
 const top=$('#demo .demo-top'),layout=document.createElement('div'),body=document.createElement('div');
 layout.className='recording-score-layout';body.className='recording-score-body';
 while(top.nextSibling)body.append(top.nextSibling);
 layout.append(body);layout.insertAdjacentHTML('beforeend',mainScorePane(s));$('#demo').append(layout);
 $('.main-score-pages').scrollTop=s.mainScoreScroll?.[s.cue]||0;
}
function recordingScreen(s,body,focus){return demoTop(focus)+sourceSessionSummary(s)+`<div class="shared-recording-screen" data-recording-view="${active.id}">${mainPanel(s)}${sourceCuePlan(s)}${body}</div>`;}
function noteTimeValue(n){return formatLocalClock(n.clockAt??Date.now());}
function sizeNoteTime(el){el.style.width=Math.max(6,el.value.length+1)+'ch';el.scrollLeft=0;}
function setNoteTimeValue(el,value){el.value=value;sizeNoteTime(el);}
function noteTime(s,t,n,place){
 const value=n.useTime===false?'—':noteTimeValue({...n,at:n.at??position(t)});
 return `<span class="note-time-control"><input type="text" class="note-time-value" data-note-time-edit="${n.id}" ${n.id==='draft'?`data-draft-clock="${t.id}"`:''} data-take="${t.id}" data-editor-place="${place}" value="${value}" readonly inputmode="text" aria-label="Clock time for note: ${esc(n.text)}" title="Click to edit clock time · Enter to save" style="width:${Math.max(6,value.length+1)}ch"><button type="button" class="note-time-reset" data-reset-note-time="${n.id}" data-take="${t.id}" data-editor-place="${place}" aria-label="Use current clock time for note: ${esc(n.text)}" title="Use current clock time"><svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="6"/><path d="M8 4v4l3 2"/></svg></button></span>`;
}
function commitNoteTime(el){
 const s=state(),t=takeById(s,el.dataset.take),n=metadataNote(t,el.dataset.noteTimeEdit);if(!n)return false;
 const value=parseLocalClock(el.value);
 if(!value){el.setCustomValidity('Use a clock time, for example 02:32:08 PM.');el.reportValidity();return false;}
 el.setCustomValidity('');const date=new Date(n.clockAt??Date.now());date.setHours(value.hours,value.minutes,value.seconds,0);
 if(n.clockAt===date.getTime()&&n.useTime!==false){setNoteTimeValue(el,noteTimeValue(n));el.readOnly=true;return true;}
 if(n.id!=='draft')rememberScoreChange(s,t);n.clockAt=date.getTime();n.useTime=true;renderDemo();
 document.querySelector(`[data-note-time-edit="${n.id}"][data-editor-place="${el.dataset.editorPlace}"]`)?.focus({preventScroll:true});return true;
}
function refreshNoteTime(el){
 const s=state(),t=takeById(s,el.dataset.take),n=metadataNote(t,el.dataset.resetNoteTime);if(!n)return;
 const now=Date.now();
 if(n.id!=='draft')rememberScoreChange(s,t);n.clockAt=now;n.useTime=true;renderDemo();
 document.querySelector(`[data-reset-note-time="${n.id}"][data-editor-place="${el.dataset.editorPlace}"]`)?.focus({preventScroll:true});
}
function noteList(s,t,score=false,place='list'){
 return `<div class="note-list" role="list" data-notes-for="${t.id}">${t.notes.filter(n=>!score||n.source===s.doc.id).map(n=>`<article role="listitem" class="note-card note-bullet ${score&&s.focusedScoreNote===n.id?'score-note-focused':''}" data-note-id="${n.id}"><div class="note-bullet-line"><span class="note-dot" aria-hidden="true">•</span><div class="note-bullet-content"><p>${esc(n.text)}</p><div class="note-meta ${score?'score-note-meta':''}">${noteTime(s,t,n,place)}${score?`<div class="note-position-stack"><div class="note-bar-line">${noteMeasure(s,t,n,score,place)}</div>${scoreSourceReference(n)}</div>`:noteMeasure(s,t,n,score,place)}${score&&n.selectedMeasures?.length>1?`<small class="note-range">Selection ${formatScoreMeasures(n.selectedMeasures)}</small>`:''}</div><button type="button" class="note-delete" data-delete-note="${n.id}" data-take="${t.id}" aria-label="Delete note: ${esc(n.text)}">Delete</button></div></div></article>`).join('')}${!t.notes.length?'<p class="notes-empty">No notes for this take yet.</p>':''}</div>`;
}
function noteBarLimit(s,n){
 const a=scoreAsset(n.source||s.doc.id),max=a?.measureRange?.[1]||Math.max(16,...Array.from({length:s.doc.pages||0},(_,i)=>scoreRegions(s,i+1)).flat().map(r=>r.measure));
 return Math.min(2000,max+10);
}
function noteMeasure(s,t,n,score,place){
 const key=t.id+':'+n.id+':'+place,all=n.measureScope==='all',limit=noteBarLimit(s,n),jump=score&&n.measure&&n.page&&n.source;
 const choices=[{value:'all',label:'All'},...Array.from({length:limit},(_,i)=>({value:String(i+1),label:String(i+1)}))];
 if(n.measure>limit)choices.push({value:String(n.measure),label:String(n.measure)});
 return `<details class="measure-picker" data-measure-menu="${n.id}" data-take="${t.id}" data-editor-place="${place}" ${s.measurePicker===key?'open':''}><summary class="${n.measure||all?(score?'measure-number':'measure-chip'):'measure-empty'}" aria-label="Choose a bar for note: ${esc(n.text)}"><span>Bar</span> <b>${all?'All':n.measure||'+'}</b><span class="measure-caret" aria-hidden="true">⌄</span></summary><div class="measure-picker-panel"><input type="text" inputmode="numeric" data-picker-measure="${n.id}" data-take="${t.id}" data-editor-place="${place}" value="${all?'All':n.measure??''}" aria-label="Bar number for note: ${esc(n.text)}" placeholder="Bar number"><div class="measure-choices" role="group" aria-label="Choose a bar number">${choices.map(({value,label})=>`<button type="button" data-pick-measure="${value}" data-note-id="${n.id}" data-take="${t.id}" data-editor-place="${place}" aria-pressed="${value===(all?'all':String(n.measure))}">${label}</button>`).join('')}</div></div></details>${jump?`<button class="measure-chip score-note-link" data-goto="${n.id}" data-take="${t.id}" aria-label="Open bar ${n.measure} in the score">↗</button>`:''}`;
}
function positionMeasurePicker(details=document.querySelector('.measure-picker[open]')){
 if(!details?.open)return;const panel=details.querySelector('.measure-picker-panel'),r=details.querySelector('summary').getBoundingClientRect();
 const left=Math.max(8,Math.min(innerWidth-panel.offsetWidth-8,r.left)),top=r.bottom+6+panel.offsetHeight<=innerHeight-8?r.bottom+6:Math.max(8,r.top-panel.offsetHeight-6);
 Object.assign(panel.style,{left:left+'px',top:top+'px'});
}
function prepareMeasurePicker(details){
 positionMeasurePicker(details);const choices=details.querySelector('.measure-choices'),chosen=choices.querySelector('[aria-pressed="true"]');
 if(chosen)choices.scrollTop=chosen.offsetTop-(choices.clientHeight-chosen.offsetHeight)/2;
 const input=details.querySelector('[data-picker-measure]');input.focus({preventScroll:true});input.select();
 if(typeof scheduleTourPosition==='function')scheduleTourPosition();
}
function closeMeasurePickers(focus=false){const open=document.querySelector('.measure-picker[open]');if(active&&state().takes)state().measurePicker=null;document.querySelectorAll('.measure-picker[open]').forEach(el=>el.open=false);if(focus)open?.querySelector('summary')?.focus({preventScroll:true});if(open&&typeof scheduleTourPosition==='function')scheduleTourPosition();}
function setNoteMeasure(take,id,value,place){
 const s=state(),t=takeById(s,take),n=metadataNote(t,id);if(!n)return;
 const all=String(value).toLowerCase()==='all';
 if(!all&&value!==''&&(!Number.isInteger(+value)||+value<1||+value>99999)){toast('Enter a whole bar number from 1 to 99999, or All.');return;}
 if(n.id!=='draft'){rememberScoreChange(s,t);if(active.id==='partituur')relocateScoreNote(n,all?'':value);}else n.source=s.doc.id;
 n.measure=all||value===''?(n.id==='draft'?'':null):+value;n.measureScope=all?'all':'bar';n.measureAuto=false;n.selectedMeasures=null;n.useMeasure=all||value!=='';
 syncSavedScorePage(n);s.measurePicker=null;renderDemo();
 document.querySelector(`.measure-picker[data-measure-menu="${id}"][data-editor-place="${place}"]>summary`)?.focus({preventScroll:true});
}
function applyMeasureInput(el){if(el)setNoteMeasure(el.dataset.take,el.dataset.pickerMeasure,el.value.trim(),el.dataset.editorPlace);}
function savedNote(s,el){return takeById(s,el.dataset.take)?.notes.find(n=>n.id===(el.dataset.noteId||el.dataset.noteAt||el.dataset.noteMeasure||el.dataset.noteDetails));}
function updateSavedNote(el){const s=state(),n=savedNote(s,el);if(!n)return;const place=el.dataset.editorPlace;
 if(el.dataset.noteOption){rememberScoreChange(s,takeById(s,el.dataset.take));const on=el.tagName==='BUTTON'?el.getAttribute('aria-pressed')!=='true':el.checked;n[el.dataset.noteOption==='time'?'useTime':'useMeasure']=on;n.editing=true;if(el.dataset.noteOption==='measure'&&on&&!n.measure)n.measure=null;}
 if(el.dataset.noteAt){const parts=el.value.trim().split(':');const valid=/^\d{1,5}:[0-5]\d(?::[0-5]\d)?$/.test(el.value.trim());if(!valid){el.setCustomValidity('Use mm:ss or hh:mm:ss, for example 00:42.');el.reportValidity();return;}el.setCustomValidity('');rememberScoreChange(s,takeById(s,el.dataset.take));n.at=parts.map(Number).reduce((a,v)=>a*60+v,0);n.editing=true;}
 if(el.dataset.noteMeasure){const value=el.value;if(el.validity.badInput||(value!==''&&(!Number.isInteger(+value)||+value<1||+value>99999))){el.setCustomValidity('Enter a whole bar number of 1 or higher, or leave it empty.');el.reportValidity();return;}el.setCustomValidity('');rememberScoreChange(s,takeById(s,el.dataset.take));if(active.id==='partituur')relocateScoreNote(n,value);n.measure=value===''?null:+value;n.measureAuto=false;n.selectedMeasures=null;n.useMeasure=value!=='';n.editing=true;syncSavedScorePage(n);}
 const attrs=['noteAt','noteMeasure','noteOption'];const key=attrs.find(k=>el.dataset[k]!==undefined),val=el.dataset[key];renderDemo();if(key){const attr='data-'+key.replace(/[A-Z]/g,c=>'-'+c.toLowerCase());const root=document.querySelector(`[data-note-id="${n.id}"][role="listitem"]`);const target=key==='noteOption'?document.querySelector(`[data-note-option="${val}"][data-note-id="${n.id}"][data-editor-place="${place}"]`):document.querySelector(`[${attr}="${val}"][data-editor-place="${place}"]`);target?.focus({preventScroll:true});}}

function composer(s,t,score=false,place='list'){return `<div class="note-composer" data-composer="${t.id}"><textarea data-editor-place="${place}" data-draft="${t.id}" aria-label="Note for ${entryLabel(t)}" placeholder="Write for ${entryLabel(t)}… Enter to add">${esc(t.draft.text)}</textarea>${active.id==='notities'?quickNoteSuggestions(t,place):''}<div class="composer-footer">${noteTime(s,t,t.draft,place)}${noteMeasure(s,t,t.draft,false,place)}<span class="enter-hint">Enter ↵</span><button data-action="add-note" data-take="${t.id}" aria-label="Add note for ${entryLabel(t)}">Add</button></div></div>`;}
function cueGeneral(s,c=s.cue,place='list'){return `<section class="cue-general"><h4>Cue notes <span>${cues[c][0]}</span></h4><div class="cue-general-list">${s.cueNotes[c].map(n=>`<article class="note-card cue-note-card note-bullet"><div class="note-bullet-line"><span class="note-dot" aria-hidden="true">•</span><p>${esc(n.text)}</p></div></article>`).join('')}</div><textarea data-editor-place="${place}" data-cue-draft="${c}" aria-label="Cue note for ${cues[c][0]}" placeholder="For the whole cue… Enter to add">${esc(s.cueDrafts[c])}</textarea><button data-action="add-cue-note" data-cue-index="${c}">Add cue note ↵</button></section>`;}
function takeCard(s,t,{write=false,score=false}={}){return `<section class="take-block ${t.rolling?'live-take':''} ${s.selected===t.id?'selected-take':''}" data-take-card="${t.id}"><header class="take-block-head"><button class="take-fold-button" data-toggle-take="${t.id}" aria-expanded="${!t.collapsed}" aria-controls="take-body-${t.id}"><b>${t.collapsed?'›':'⌄'} ${entryLabel(t)}</b><span>${t.rolling?'● RECORDING':'Stopped · '+time(t.duration)}</span></button><div class="take-tools">${starRating(t.rating,t.id,cues[t.cue][0]+' '+entryLabel(t))}<button class="best" data-take-best="${t.id}" aria-pressed="${t.best}">Best</button><button class="alt" data-take-alt="${t.id}" aria-pressed="${!!t.alt}" aria-label="${entryLabel(t)} as alternate: ${altLabel(s,t.cue,t.id)}">${altLabel(s,t.cue,t.id)}</button></div></header><div id="take-body-${t.id}" ${t.collapsed?'hidden':''}>${noteList(s,t,score)}${write?composer(s,t,score):''}</div></section>`;}
function takeSummary(s,t){return `<div class="take-summary-row"><button data-select-take="${t.id}" aria-expanded="false" aria-label="Open notes for ${entryLabel(t)}"><b>${entryLabel(t)}</b><span>${t.rolling?'● Recording':'Stopped · '+time(t.duration)}</span><small>${t.notes.length} ${t.notes.length===1?'note':'notes'} · Open →</small></button>${starRating(t.rating,t.id,cues[t.cue][0]+' '+entryLabel(t))}</div>`;}
function groupedList(s,{mode='selected',filter=0}={}){return `<div class="grouped-list">${cues.map((c,j)=>{const open=s.open.has(j),visible=s.takes[j].filter(t=>(t.rating||0)>=filter);return `<section class="cue-group ${j===s.cue?'current':''}">${cueHeader(s,c,j,s.takes[j].length,open,'details-'+j)}<div class="cue-details focused-cue-details" id="details-${j}" ${open?'':'hidden'}><div class="nested-takes">${visible.length?visible.map(t=>mode==='all'||s.selected===t.id?`<div class="selected-list-take">${takeCard(s,t,{write:true})}</div>`:takeSummary(s,t)).join(''):`<div class="empty">${s.takes[j].length?'No takes match this filter.':'No takes yet.'}</div>`}</div><details class="cue-general-fold" data-cue-fold="${j}" ${s.cueFold.has(j)?'open':''}><summary>Cue notes <span>${s.cueNotes[j].length} ${s.cueNotes[j].length===1?'note':'notes'}</span></summary>${cueGeneral(s,j)}</details></div></section>`;}).join('')}</div>`;}
function controls(){return state().controlsPrevious?demoTop('Previous layout')+controlVersionButtons(state())+previousControls().replace(demoTop(variant==='A'?'A · One scrolling workspace':'B · Two separate columns'),''):calmControls();}
function previousControls(){const s=state();const heading=variant==='A'?'Main controls at the top. Compact bar after scrolling.':'Controls stay on the left. Cues and notes scroll on the right.';const explanation=variant==='A'?'The main controls remain at the top. Scroll down to keep a compact start/stop bar within reach.':'The controls stay on the left. Select a take on the right to read or write notes.';return demoTop(variant==='A'?'A · One scrolling workspace':'B · Two separate columns')+sourceSessionSummary(s)+`<div class="control-comparison"><span class="option-letter">${variant}</span><div><h3>${heading}</h3><p>${explanation}</p></div></div><div class="control-layout-key"><span><i class="key-fixed"></i> Stays visible: ${variant==='A'?'compact bar when scrolling':'controls on the left'}</span><span><i class="key-scroll"></i> Scrolls: ${variant==='A'?'main controls and cue list':'cues, takes and notes on the right'}</span><button data-action="scroll-takes">${variant==='A'?'Try: scroll to the takes ↓':'Try: scroll the list ↓'}</button></div>`+(variant==='A'?`<div class="control-scroll" id="cue-scroll" tabindex="0" aria-label="Scrolling recording workspace"><div class="sticky-slot" aria-hidden="true">${transport(s)}</div>${mainPanel(s)}${sourceCuePlan(s)}<div class="region-label scroll-region">Scrollable · cues, takes & notes</div>${groupedList(s)}</div>`:`<div class="control-side">${mainPanel(s,true)}<div class="control-scroll side-scroll" id="cue-scroll" tabindex="0" aria-label="Scrolling cue and take list">${sourceCuePlan(s)}<div class="region-label scroll-region">Scroll here · cues, takes & notes</div>${groupedList(s)}</div></div>`);}

function takePicker(s){return `<div class="take-picker horizontal" role="group" aria-label="Select a take">${s.takes[s.cue].map(t=>`<button data-select-take="${t.id}" aria-pressed="${s.selected===t.id}"><b>${entryLabel(t)}</b><small>${t.rolling?'● Recording':'Stopped · '+time(t.duration)}</small></button>`).join('')}</div>`;}
function selectedNotes(s,score=false){const t=takeById(s,s.selected);return `<section class="selected-note-panel"><div class="selected-note-head"><span class="eyebrow">${cues[t.cue][0]} · ${cues[t.cue][1]}</span><h3><button class="take-fold-button" data-toggle-take="${t.id}" aria-expanded="${!t.collapsed}" aria-controls="selected-body-${t.id}">${t.collapsed?'›':'⌄'} Notes for <strong>${entryLabel(t)}</strong></button></h3><span class="take-state ${t.rolling?'is-live':''}">${t.rolling?'● Recording':'Stopped take'} · <b data-live="${t.id}">${time(position(t))}</b></span><div class="selected-take-rating">${starRating(t.rating,t.id,cues[t.cue][0]+' '+entryLabel(t))}</div></div><div id="selected-body-${t.id}" ${t.collapsed?'hidden':''}>${!t.rolling?`<label class="position-control">Position in this take <input type="range" min="0" max="${t.duration}" value="${position(t)}" data-position="${t.id}" aria-label="Demo position in ${entryLabel(t)}"></label>`:''}${noteList(s,t,score)}${composer(s,t,score)}</div></section>`;}
function notes(){const s=state();return recordingScreen(s,groupedList(s,{mode:variant==='A'?'all':'selected'}),'Take notes');}
function scoreView(s){return productionScoreView(s);}
function score(){if(variant==='B')return scoreWorkflow();const s=state();return `<div class="score-layout cutlist-layout">${scoreSidebar(s)}${scoreView(s)}</div>`;}
function visibleStopButton(el){if(!el||getComputedStyle(el).visibility==='hidden'||el.closest('[inert]'))return false;let box=el.getBoundingClientRect();let left=Math.max(0,box.left),top=Math.max(0,box.top),right=Math.min(innerWidth,box.right),bottom=Math.min(innerHeight,box.bottom);for(let p=el.parentElement;p&&p!==document.body;p=p.parentElement){const cs=getComputedStyle(p);if(cs.overflowY!=='visible'||cs.overflowX!=='visible'){const r=p.getBoundingClientRect();left=Math.max(left,r.left);top=Math.max(top,r.top);right=Math.min(right,r.right);bottom=Math.min(bottom,r.bottom);}}return right-left>30&&bottom-top>20;}
function syncRecordingDock(){const dock=$('#recording-dock');if(!dock)return;const s=active&&state(),t=s?.takes?running(s):null;if(!t){dock.hidden=true;dock.dataset.key='';return;}const key=active.id+':'+t.id;if(dock.dataset.key!==key){dock.dataset.key=key;dock.innerHTML=`<div><strong>${cues[t.cue][0]} · ${entryLabel(t)}</strong><span>● Recording · <b data-live="${t.id}">${time(position(t))}</b></span></div><button class="dock-stop" data-action="record">■ Stop ${t.kind==='overdub'?'overdub':'take'} <kbd>⌘ Enter</kbd></button>`;}dock.hidden=Array.from(document.querySelectorAll('#demo .stop,#demo .composer-stop,.proposal-live-bar .stop')).some(visibleStopButton);}
let recordingControlsFrame=0;
function scheduleRecordingControls(){if(recordingControlsFrame)return;recordingControlsFrame=requestAnimationFrame(()=>{recordingControlsFrame=0;syncSticky();syncRecordingDock();});}
document.addEventListener('scroll',scheduleRecordingControls,true);
window.addEventListener('resize',scheduleRecordingControls);
function syncSticky(){if(active?.id!=='bediening'||variant!=='A')return;const scroll=$('#cue-scroll'),button=$('#main-panel .record'),slot=$('.sticky-slot');if(!scroll||!button||!slot)return;const top=scroll.getBoundingClientRect().top+scroll.clientTop;const threshold=slot.classList.contains('is-stuck')?top+4:top;const visible=button.getBoundingClientRect().top<threshold;slot.classList.toggle('is-stuck',visible);slot.setAttribute('aria-hidden',!visible);slot.inert=!visible;}
function renderDemo(){if(!active)return;const takePicker=document.querySelector('.score-take-picker'),takePickerTop=takePicker?.scrollTop;const overview=document.querySelector('.all-takes-scroll'),overviewPosition=overview?{top:overview.scrollTop,left:overview.scrollLeft}:null;const previousScore=$('.main-score-pages');if(previousScore){const s=state();s.mainScoreScroll??={};s.mainScoreScroll[previousScore.dataset.scoreCue]=previousScore.scrollTop;}const scoreScroll=$('.score-canvas'),scorePaper=$('.score-paper');const scorePosition=scoreScroll&&scorePaper?{source:scorePaper.dataset.scoreSource,page:scorePaper.dataset.scorePage,take:scorePaper.dataset.scoreTake,top:scoreScroll.scrollTop,left:scoreScroll.scrollLeft}:null;const scroll=$('#cue-scroll')?.scrollTop||0;const focused=document.activeElement;const focusKey=focused?.dataset?Object.entries(focused.dataset).find(([k])=>['draft','measureInput','cueDraft','openCue','cue','best','takeBest','selectTake','selectCue','sessionCue','toggleTake','scoreToggle'].includes(k)):null;let selection=null;try{selection=[focused.selectionStart,focused.selectionEnd];}catch{}
 const s=state();if(s.takes){for(const t of allTakes(s))if(t.rolling&&t.started===null)t.started=Date.now();}
 if(s.cueFold)document.querySelectorAll('[data-cue-fold]').forEach(el=>el.open?s.cueFold.add(+el.dataset.cueFold):s.cueFold.delete(+el.dataset.cueFold));
 $('#demo').innerHTML=({'cue-take':hierarchy,bediening:controls,notities:notes,partituur:score,planning:planningDemo}[active.id])();
 mountMainScore(s);syncFullscreenButtons();
 if(takePickerTop!==undefined){const next=document.querySelector('.score-take-picker');if(next)next.scrollTop=takePickerTop;}
 if(overviewPosition){const next=document.querySelector('.all-takes-scroll');if(next){next.scrollTop=overviewPosition.top;next.scrollLeft=overviewPosition.left;}}
 if($('#cue-scroll')){$('#cue-scroll').scrollTop=scroll;}
 if(scorePosition&&scorePosition.source===s.doc?.id){const canvas=$('.score-canvas');if(canvas){canvas.scrollTop=scorePosition.top;canvas.scrollLeft=scorePosition.left;}}if(s.pendingScoreScroll){const canvas=$('.score-canvas');if(canvas){if(s.pendingScoreScroll.document)window.scrollTo({top:window.scrollY+canvas.getBoundingClientRect().top+s.pendingScoreScroll.top,behavior:'auto'});else{canvas.scrollTop=s.pendingScoreScroll.top;canvas.scrollLeft=s.pendingScoreScroll.left;}}delete s.pendingScoreScroll;}syncSticky();syncRecordingDock();if(focusKey){const attr='data-'+focusKey[0].replace(/[A-Z]/g,c=>'-'+c.toLowerCase());const place=focused.dataset.editorPlace;const target=document.querySelector(`[${attr}="${focusKey[1]}"]${place?`[data-editor-place="${place}"]`:""}`);if(target){target.focus({preventScroll:true});if(selection&&selection[0]!==null&&target.setSelectionRange)target.setSelectionRange(...selection);}}
 if(active.id==='partituur'){syncScoreCommentDialog();refreshScoreTextPositions();}
}
function stepCue(s,direction){const next=s.cue+direction;if(next>=0&&next<cues.length)selectCue(s,next);}
function selectCue(s,j){if(active.id==='partituur'){selectScoreCue(s,j);return;}if(s.takes&&running(s)&&j!==s.cue){toast('Stop the active take before switching cues.');return;}s.cue=j;s.open.add(j);if(s.takes){const t=s.takes[j].at(-1);s.selected=t?.id||null;if(t)t.collapsed=false;}renderDemo();}
function performRecordingAction(s){
 if(s.unified&&s.sessionPausedAt){proposalSessionBreak(s);return;}
 if(s.unified&&!s.sessionStarted){
  const reopening=s.sessionEnded;s.sessionStarted=true;s.sessionEnded=false;
  if(!reopening&&s.scoreWorkflowClock){const clock=s.scoreWorkflowClock;if(clock.fixedEndAt){clock.plannedEndAt=clock.fixedEndAt;clock.booked=Math.max(0,Math.floor((clock.fixedEndAt-Date.now())/1000));}else clock.plannedEndAt=Date.now()+s.booked*60000;}
  if(s.scoreWorkflowClock){s.scoreWorkflowClock.started=Date.now();s.scoreWorkflowClock.cueStarted=Date.now();}
  renderDemo();return;
 }
 toggleRecord(s);
}
function toggleRecord(s,kind='take'){
 const t=running(s);if(active.id==='partituur'&&!t)rememberScoreView(s);
 if(t){
  t.duration=position(t);t.cursor=t.duration;t.rolling=false;
  if(t.takeLog)t.takeLog.loggedEndAt=new Date().toISOString();
 }else{
  const n=nextEntryNumber(s,s.cue,kind),next=newTake(s.cue,n,true,kind);
  next.base=0;next.cursor=0;next.duration=0;next.started=Date.now();next.rating=0;next.best=false;
  // These are our manual transport events, not an acknowledgement from a DAW.
  next.takeLog={id:crypto.randomUUID?.()||Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join(''),sessionId:s.sessionId??null,cueCode:cues[s.cue][0],loggedStartAt:new Date(next.started).toISOString(),loggedEndAt:null,timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone,utcOffsetMinutes:-new Date(next.started).getTimezoneOffset(),source:'manual-demo-transport'};
  s.takes[s.cue].push(next);s.selected=next.id;s.open.add(s.cue);
  if(active.id==='partituur'){s.scoreCompared??={};s.scoreCompared[s.cue]=[next.id];restoreScoreView(s);}
 }
 renderDemo();
}
function addNote(id,place){const s=state(),t=takeById(s,id);if(!t||!t.draft.text.trim())return;const d=t.draft;if(d.measure!==''&&(!Number.isInteger(Number(d.measure))||+d.measure<1||+d.measure>99999)){toast('Enter a valid bar number or leave it empty.');return;}t.notes.push({id:'note-'+(++s.noteSerial),text:d.text.trim(),clockAt:d.clockAt??Date.now(),createdAt:Date.now(),useTime:true,useMeasure:d.measure!=='',at:d.at??position(t),originalAt:d.originalAt??d.at??position(t),measureScope:d.measureScope||'bar',measure:d.measure===''?null:Number(d.measure),page:d.page??(active.id==='partituur'||s.unified?s.page:null),measureAuto:!!d.measureAuto,source:d.source??(active.id==='partituur'||s.unified?s.doc.id:null)});syncSavedScorePage(t.notes.at(-1));t.draft={...draft(),measure:d.measure,measureScope:d.measureScope,page:d.page,source:d.source};renderDemo();$(`[data-draft="${id}"]${place?`[data-editor-place="${place}"]`:""}`)?.focus({preventScroll:true});}
function addCueNote(c,place){const s=state(),text=s.cueDrafts[c].trim();if(!text)return;s.cueNotes[c].push({id:'cue-note-'+(++s.noteSerial),text});s.cueDrafts[c]='';renderDemo();$(`[data-cue-draft="${c}"]${place?`[data-editor-place="${place}"]`:""}`)?.focus({preventScroll:true});}
function selectMeasure(n){const s=state(),t=takeById(s,s.selected),loc=scoreLocation(s.doc.id,n);if(!loc){toast('This bar has no mapped score location yet.');return;}s.measure=n;s.page=loc.page;s.scoreFocus=null;if(t){t.draft.measureAuto=false;t.draft.measure=n;t.draft.page=s.page;t.draft.source=s.doc.id;}renderDemo();revealScoreMeasure();}
function gotoNote(id,take){const s=state(),t=takeById(s,take),n=t?.notes.find(n=>n.id===id);if(!n)return;if(n.measureScope==='all')return;if(n.source&&n.source!==s.doc.id){toast('Open the score version associated with this note first.');return;}if(active.id==='partituur')s.cutlistView='score';s.selected=t.id;s.focusedScoreNote=n.id;s.page=n.page||s.page;s.measure=n.measure;s.scoreFocus={page:s.page,measure:n.measure,instruments:n.instruments||scoreInstrumentIds};renderDemo();revealScoreMeasure();}
function setPage(value){const s=state(),n=Number(value);if(!Number.isInteger(n)||n<1||n>(s.doc.pages||9999)){toast('Choose an existing PDF page.');renderDemo();return;}s.page=n;s.measure=null;renderDemo();}
async function copyText(text,preview,details,message){try{await navigator.clipboard.writeText(text);toast(message);return;}catch{}const temp=document.createElement('textarea');temp.value=text;temp.style.position='fixed';temp.style.opacity='0';document.body.append(temp);temp.select();let copied=false;try{copied=document.execCommand('copy');}catch{}temp.remove();if(copied){toast(message);return;}if(details)details.open=true;if(preview){const sel=window.getSelection(),range=document.createRange();range.selectNodeContents(preview);sel.removeAllRanges();sel.addRange(range);preview.focus();}toast('Prompt geselecteerd. Kopieer met ⌘C of Ctrl+C.');}
