 if(b.dataset.action==='download-control-review'){saveFile('Beoordeling-suggestie-2.md','# Beoordeling suggestie 2\n\n'+controlReviewItems.map(([id,label])=>'- '+label+': '+(controlReviewChoices[id]||'Nog niet beoordeeld')).join('\n'));return;}
