 if(b.dataset.quickNote){const t=takeById(s,b.dataset.take);t.draft.clockAt??=Date.now();if(t.draft.at===null)t.draft.at=position(t);t.draft.text+=(t.draft.text?' · ':'')+b.dataset.quickNote;renderDemo();document.querySelector(`[data-draft="${t.id}"][data-editor-place="${b.dataset.editorPlace}"]`)?.focus({preventScroll:true});return;}
 if(b.dataset.resetNoteTime){refreshNoteTime(b);return;}
